233	// --- in 条件：解码后字符串精确相等的回归保障 -----------------------------------
234	//
235	// 这组测试保护 in 列表的既有行为：上下文值按 JSON 解码后的字符串与每个候选值
236	// 逐项精确比较，只有完全相等才算属于列表。直接写出的字符与合法的 Unicode
237	// 转义（含必须成对的代理项转义）表达同一文字时等价；大小写、首尾空白、
238	// 预组合字符与“字母+组合附加符号”序列仍按不同字符串处理。
239	//
240	// 下列常量用拼接方式写出 JSON 转义文本（与本文件既有写法一致），避免在源码
241	// 层面把转义写法与直接字符混为一谈。
242	const (
243		// inEscEAcute 是 é（U+00E9）的转义写法。
244		inEscEAcute = `\u` + `00E9`
245		// inEscCombine 是 "e" 后接组合附加符号 U+0301 的转义写法（与预组合 é 不同）。
246		inEscCombine = `e\u` + `0301`
247		// inEscGrin 是 😀（U+1F600）的一对代理项转义写法。
248		inEscGrin = (`\u` + `D83D`) + (`\u` + `DE00`)
249		// inEscReplace 是 U+FFFD 的转义写法。
250		inEscReplace = `\u` + `FFFD`
251		// inEscTier 是属性名 tier 四个字母各自转义后的写法。
252		inEscTier = (`\u` + `0074`) + (`\u` + `0069`) + (`\u` + `0065`) + (`\u` + `0072`)
253	)
254	
255	// inCfg 拼出只有一个启用开关、一条 in 规则（id=r1、value=true、default=false）
256	// 的配置；attrJSON 是属性名的 JSON 字符串内容，listJSON 是完整的候选值数组。
257	func inCfg(attrJSON, listJSON string) string {
258		return `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[` +
259			`{"id":"r1","value":true,"conditions":[` +
260			`{"attribute":"` + attrJSON + `","op":"in","value":` + listJSON + `}]}]}]}`
261	}
262	
263	// TestInDecodedSpellingEquivalence 验证同一属性名、列表候选值或上下文值，无论
264	// 用直接字符还是合法 JSON Unicode 转义书写（包括需要一对代理项转义的字符），
265	// 解码后都命中同一条规则，得到完全一致的 key、value、reason 与 ruleId；配置
266	// 与上下文可以分别使用不同写法。
267	func TestInDecodedSpellingEquivalence(t *testing.T) {
268		configs := []namedConfig{
269			{"direct candidates", inCfg(`tier`, `["é","😀","other"]`)},
270			{"escaped candidates", inCfg(`tier`, `["`+inEscEAcute+`","`+inEscGrin+`","other"]`)},
271			{"mixed candidates", inCfg(`tier`, `["é","`+inEscGrin+`","other"]`)},
272			{"escaped attribute", inCfg(inEscTier, `["é","😀","other"]`)},
273		}
274		contexts := []struct {
275			name string
276			raw  string
277		}{
278			{"e-acute direct", `{"tier":"é"}`},
279			{"e-acute escaped", `{"tier":"` + inEscEAcute + `"}`},
280			{"emoji direct", `{"tier":"😀"}`},
281			{"emoji surrogate pair", `{"tier":"` + inEscGrin + `"}`},
282			{"plain ascii", `{"tier":"other"}`},
283			{"escaped attr, direct value", `{"` + inEscTier + `":"é"}`},
284			{"escaped attr, escaped value", `{"` + inEscTier + `":"` + inEscGrin + `"}`},
285		}
286		id := "r1"
287		want := EvalResult{Key: "f", Value: true, Reason: EvalRule, RuleID: &id}
288		var reference EvalResult
289		for ci, cfg := range configs {
290			for _, cx := range contexts {
291				t.Run(cfg.name+"/"+cx.name, func(t *testing.T) {
292					got := eval(t, cfg.raw, "f", cx.raw)
293					if !got.Equals(want) {
294						t.Fatalf("decoded spellings must hit the same rule: got %+v, want %+v", got, want)
295					}
296					if ci == 0 && cx.name == "e-acute direct" {
297						reference = got
298					} else if !got.Equals(reference) {
299						t.Fatalf("result drifted across spellings: got %+v, want %+v", got, reference)
300					}
301				})
302			}
303		}
304	}
