306	// TestInExactStringBoundaries 验证外形相近但解码后不相等的字符串不得归入列表：
307	// 大小写、首尾空白、预组合 é（U+00E9）与 "e 加 U+0301" 的序列、邻近码位的
308	// 表情符号都按原样区分。列表明确包含组合序列时，才匹配该序列。
309	func TestInExactStringBoundaries(t *testing.T) {
310		cfg := inCfg(`tier`, `["é","😀","AbC"]`)
311		misses := []struct {
312			name string
313			raw  string
314		}{
315			{"uppercase precomposed", `{"tier":"É"}`},
316			{"lowercase ascii", `{"tier":"abc"}`},
317			{"leading space", `{"tier":" é"}`},
318			{"trailing space", `{"tier":"é "}`},
319			{"combining sequence vs precomposed", `{"tier":"` + inEscCombine + `"}`},
320			{"replacement char", `{"tier":"` + inEscReplace + `"}`},
321			{"neighboring emoji code point", `{"tier":"😃"}`},
322			{"missing attribute", `{"other":"é"}`},
323		}
324		for _, tc := range misses {
325			t.Run(tc.name, func(t *testing.T) {
326				got := eval(t, cfg, "f", tc.raw)
327				if got.Reason != EvalDefault || got.RuleID != nil || got.Value {
328					t.Fatalf("lookalike must not belong to the list: got %+v", got)
329				}
330			})
331		}
332	
333		// 列表明确包含 e + U+0301：组合序列命中，预组合 é 反而不命中。
334		cfgCombining := inCfg(`tier`, `["`+inEscCombine+`"]`)
335		if got := eval(t, cfgCombining, "f", `{"tier":"`+inEscCombine+`"}`); got.Reason != EvalRule || !got.Value {
336			t.Fatalf("explicit combining sequence must match itself: %+v", got)
337		}
338		if got := eval(t, cfgCombining, "f", `{"tier":"é"}`); got.Reason != EvalDefault {
339			t.Fatalf("precomposed é must not match an e+U+0301 list: %+v", got)
340		}
341	}
