375	// TestInAttributeNameExactLookup 验证 in 条件的属性名按解码后的文字精确查找：
376	// 大小写、首尾空白、预组合字符与组合序列外形接近的另一个属性不能被读到；
377	// 合法 Unicode 转义书写的属性名与直接字符同名，可以跨写法命中。
378	func TestInAttributeNameExactLookup(t *testing.T) {
379		cfg := inCfg(`tier`, `["a"]`)
380		// 外形接近的属性名下即使放着列表内的值，也不能让条件成立。
381		for _, tc := range []struct {
382			name string
383			ctx  string
384		}{
385			{"capitalized", `{"Tier":"a"}`},
386			{"upper", `{"TIER":"a"}`},
387			{"leading space", `{" tier":"a"}`},
388			{"trailing space", `{"tier ":"a"}`},
389			{"emoji attribute", `{"😀":"a"}`},
390		} {
391			t.Run(tc.name, func(t *testing.T) {
392				if got := eval(t, cfg, "f", tc.ctx); got.Reason != EvalDefault {
393					t.Fatalf("lookalike attribute must not satisfy an in condition: %+v", got)
394				}
395			})
396		}
397		// 同名属性放着非成员值、近名属性放着成员值：必须读精确同名属性而不命中。
398		if got := eval(t, cfg, "f", `{"tier":"z","Tier":"a"}`); got.Reason != EvalDefault {
399			t.Fatalf("exact attribute lookup must ignore similarly named siblings: %+v", got)
400		}
401		// 精确同名属性存在且值为成员：命中。
402		if got := eval(t, cfg, "f", `{"Tier":"z","tier":"a"}`); got.Reason != EvalRule {
403			t.Fatalf("exact attribute name must be found: %+v", got)
404		}
405		// 转义书写的属性名与直接字符同名：跨写法命中。
406		if got := eval(t, cfg, "f", `{"`+inEscTier+`":"a"}`); got.Reason != EvalRule {
407			t.Fatalf("escaped attribute spelling must find the same attribute: %+v", got)
408		}
409	
410		// 属性名本身区分预组合 "café" 与 "cafe"+U+0301，且转义写法与直接字符同义。
411		cfgAccent := inCfg(`café`, `["a"]`)
412		if got := eval(t, cfgAccent, "f", `{"café":"a"}`); got.Reason != EvalRule {
413			t.Fatalf("precomposed attribute name must be found exactly: %+v", got)
414		}
415		if got := eval(t, cfgAccent, "f", `{"caf`+inEscCombine+`":"a"}`); got.Reason != EvalDefault {
416			t.Fatalf("combining-sequence attribute name must not satisfy a precomposed lookup: %+v", got)
417		}
418		cfgAccentEsc := inCfg(`caf`+inEscEAcute, `["a"]`)
419		if got := eval(t, cfgAccentEsc, "f", `{"café":"a"}`); got.Reason != EvalRule {
420			t.Fatalf("escaped attribute spelling must find the literal-named attribute: %+v", got)
421		}
422	
423		// 需要代理项对的属性名同样按解码文字精确查找。
424		cfgEmoji := inCfg(`😀`, `["a"]`)
425		if got := eval(t, cfgEmoji, "f", `{"`+inEscGrin+`":"a"}`); got.Reason != EvalRule {
426			t.Fatalf("surrogate-pair attribute spelling must equal the literal name: %+v", got)
427		}
428		if got := eval(t, cfgEmoji, "f", `{"😃":"a"}`); got.Reason != EvalDefault {
429			t.Fatalf("a neighboring emoji must be a different attribute: %+v", got)
430		}
431	}
