433	// TestInListOrderAndDuplicates 验证列表顺序变化或加入已有候选值不改变成员判断；
434	// 重复候选是合法配置，不被误报为重复字段或重复配置。
435	func TestInListOrderAndDuplicates(t *testing.T) {
