438			{"reordered", inCfg(`tier`, `["é","a","b"]`)},
439			{"escaped spelling", inCfg(`tier`, `["`+inEscEAcute+`","a","b"]`)},
440			{"with duplicates", inCfg(`tier`, `["a","b","a","é","b","é"]`)},
441		}
442		contexts := []struct {
443			raw       string
444			wantMatch bool
445		}{
446			{`{"tier":"a"}`, true},
447			{`{"tier":"b"}`, true},
448			{`{"tier":"é"}`, true},
449			{`{"tier":"` + inEscEAcute + `"}`, true},
450			{`{"tier":"c"}`, false},
451			{`{"tier":" a"}`, false},
452			{`{"tier":""}`, false},
453			{`{}`, false},
454		}
455		for _, cfg := range configs {
456			// 含重复候选的配置本身必须被接受（数组中的重复元素不是重复字段）。
457			mustParseConfig(t, cfg.raw)
458			for _, cx := range contexts {
459				t.Run(cfg.name+"/"+cx.raw, func(t *testing.T) {
