461					if cx.wantMatch {
462						if got.Reason != EvalRule || got.RuleID == nil || *got.RuleID != "r1" || !got.Value {
463							t.Fatalf("member judgment changed: got %+v", got)
464						}
465					} else if got.Reason != EvalDefault || got.RuleID != nil {
466						t.Fatalf("non-member judgment changed: got %+v", got)
467					}
468				})
469			}
