528	// TestInEmptyStringMemberVsMissing 验证空字符串作为列表成员时，属性显式给出
529	// 空字符串才算命中；属性缺失（或值为空白）不成立，并继续检查后面的规则。
530	func TestInEmptyStringMemberVsMissing(t *testing.T) {
531		cfg := `{"flags":[{"key":"f","enabled":true,"default":true,"rules":[
532			{"id":"r-empty","value":false,"conditions":[
533				{"attribute":"plan","op":"eq","value":"pro"},
534				{"attribute":"note","op":"in","value":["","a"]}]},
535			{"id":"r-allow","value":true,"conditions":[
536				{"attribute":"region","op":"eq","value":"cn"}]}]}]}`
537		emptyID, allowID := "r-empty", "r-allow"
538	
539		// note 显式为空字符串（或成员 "a"）且另一条件成立：前一条定案 false。
540		for _, ctxRaw := range []string{
541			`{"plan":"pro","note":"","region":"cn"}`,
542			`{"plan":"pro","note":"a","region":"cn"}`,
543		} {
544			got := eval(t, cfg, "f", ctxRaw)
545			want := EvalResult{Key: "f", Value: false, Reason: EvalRule, RuleID: &emptyID}
546			if !got.Equals(want) {
547				t.Fatalf("explicit empty-string member must win the earlier rule (%s): got %+v", ctxRaw, got)
548			}
549		}
550		// 属性缺失或值不在列表：前一条不成立，继续到 r-allow。
551		for _, ctxRaw := range []string{
552			`{"plan":"pro","region":"cn"}`,
553			`{"plan":"pro","note":"b","region":"cn"}`,
554			`{"plan":"pro","note":" ","region":"cn"}`,
555		} {
556			got := eval(t, cfg, "f", ctxRaw)
557			want := EvalResult{Key: "f", Value: true, Reason: EvalRule, RuleID: &allowID}
558			if !got.Equals(want) {
559				t.Fatalf("missing/non-member note must continue to the later rule (%s): got %+v", ctxRaw, got)
560			}
561		}
562	
563		// 只有一个空串候选的列表：空串命中；空白与属性缺失都不命中。
564		cfgOnlyEmpty := inCfg(`note`, `[""]`)
565		if got := eval(t, cfgOnlyEmpty, "f", `{"note":""}`); got.Reason != EvalRule {
566			t.Fatalf("empty-only list matches explicit empty string: %+v", got)
567		}
568		if got := eval(t, cfgOnlyEmpty, "f", `{"note":" "}`); got.Reason != EvalDefault {
569			t.Fatalf("whitespace is not the empty-string member: %+v", got)
570		}
571		if got := eval(t, cfgOnlyEmpty, "f", `{}`); got.Reason != EvalDefault {
572			t.Fatalf("missing attribute does not satisfy empty-string membership: %+v", got)
573		}
574	}
