615	func TestMarshalResultShape(t *testing.T) {
616		cfg := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
617			{"id":"r-1","value":true,"conditions":[{"attribute":"a","op":"eq","value":"x"}]}]}]}`
618		got := eval(t, cfg, "f", `{"a":"x"}`)
