1154	// TestCLIEvaluateInDecodedSpellingEquivalence 端到端验证：同一属性名、列表
1155	// 候选值或上下文值，无论用直接字符还是合法 Unicode 转义（含代理项对）书写，
1156	// evaluate 都输出逐字节一致的单个 JSON 对象（key、value、reason、ruleId
1157	// 完全一致）；配置与上下文可分别使用不同写法。
1158	func TestCLIEvaluateInDecodedSpellingEquivalence(t *testing.T) {
1159		configs := []struct {
1160			name string
1161			raw  string
1162		}{
1163			{"direct", cliInListConfig(`["é","😀","other"]`)},
1164			{"escaped", cliInListConfig(`["` + cliEscEA + `","` + cliEscGR + `","other"]`)},
1165			{"mixed", cliInListConfig(`["é","` + cliEscGR + `","other"]`)},
1166		}
1167		contexts := []struct {
1168			name string
1169			raw  string
1170		}{
1171			{"e-acute direct", `{"tier":"é"}`},
1172			{"e-acute escaped", `{"tier":"` + cliEscEA + `"}`},
1173			{"emoji direct", `{"tier":"😀"}`},
1174			{"emoji surrogate pair", `{"tier":"` + cliEscGR + `"}`},
1175			{"plain ascii", `{"tier":"other"}`},
1176		}
1177		var reference string
1178		for ci, cfg := range configs {
1179			for _, cx := range contexts {
