			`{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],
				"meta":{"n":1e400,"n":2}}]}`,
			"f",
			[]string{"config", "duplicate field", `config.flags[0].meta.n`},
			[]string{"invalid JSON"},
		},
		{
			"duplicate after 400-digit integer in extra object",
			`{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],
				"meta":{"n":` + hugeInt + `,"n":2}}]}`,
			"f",
			[]string{"config", "duplicate field", `config.flags[0].meta.n`},
