		t.Fatalf("f1: unexpected payload: %v", got)
	}
	got, _ = evalSuccess(t, h, "f2")
	if got["key"] != "f2" || got["value"] != false || got["reason"] != "rule" || got["ruleId"] != "r-é🚀" {
